import{_ as d,o as a,c as e,a2 as s}from"./chunks/framework.yo2CxoV2.js";const k=JSON.parse('{"title":"API 与数据契约","description":"","frontmatter":{},"headers":[],"relativePath":"reference/api.md","filePath":"reference/api.md","lastUpdated":1794341682000}'),i={name:"reference/api.md"};function o(p,t,r,l,n,c){return a(),e("div",null,[...t[0]||(t[0]=[s(`<h1 id="api-与数据契约" tabindex="-1">API 与数据契约 <a class="header-anchor" href="#api-与数据契约" aria-label="Permalink to &quot;API 与数据契约&quot;">​</a></h1><p>接口相对于插件挂载点。例如挂载到 <code>/admin/</code> 时，下面的 <code>/api/me/</code> 实际为 <code>/admin/api/me/</code>。</p><p><code>model_key</code> 使用 <code>app_label.model_name</code>，例如 <code>projects.project</code>。下表管理接口保留 Django Session 与 CSRF 机制，外部只读数据服务的 Bearer 凭据不能替代管理会话。</p><h2 id="常用接口" tabindex="-1">常用接口 <a class="header-anchor" href="#常用接口" aria-label="Permalink to &quot;常用接口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>相对地址</th><th>用途</th></tr></thead><tbody><tr><td>GET</td><td><code>/api/config/</code></td><td>登录及界面公开配置、CSRF 信息</td></tr><tr><td>POST</td><td><code>/api/login/</code></td><td>登录</td></tr><tr><td>POST</td><td><code>/api/logout/</code></td><td>退出</td></tr><tr><td>GET</td><td><code>/api/me/</code></td><td>当前账号与能力</td></tr><tr><td>GET</td><td><code>/api/captcha/</code></td><td>刷新验证码</td></tr><tr><td>POST</td><td><code>/api/password/</code></td><td>修改自己的密码</td></tr><tr><td>GET / POST</td><td><code>/api/account-password/&lt;model_key&gt;/</code></td><td>原生用户密码表单，使用 object_id 查询</td></tr><tr><td>GET</td><td><code>/api/menu/</code></td><td>当前账号的可访问菜单</td></tr><tr><td>GET</td><td><code>/api/meta/&lt;model_key&gt;/</code></td><td>字段、权限、默认值、分组和明细配置</td></tr><tr><td>GET</td><td><code>/api/list/&lt;model_key&gt;/</code></td><td>列表</td></tr><tr><td>GET</td><td><code>/api/detail/&lt;model_key&gt;/</code></td><td>详情，使用 object_id 查询</td></tr><tr><td>GET</td><td><code>/api/options/&lt;model_key&gt;/&lt;field_name&gt;/</code></td><td>关联选项</td></tr><tr><td>POST</td><td><code>/api/save/&lt;model_key&gt;/</code></td><td>主表及提交的关联明细保存</td></tr><tr><td>POST</td><td><code>/api/cell/&lt;model_key&gt;/</code></td><td>行内编辑</td></tr><tr><td>GET</td><td><code>/api/export/&lt;model_key&gt;/</code></td><td>CSV 导出</td></tr><tr><td>POST</td><td><code>/api/delete-preview/&lt;model_key&gt;/</code></td><td>删除影响预览</td></tr><tr><td>POST</td><td><code>/api/delete/&lt;model_key&gt;/</code></td><td>删除</td></tr><tr><td>GET</td><td><code>/api/trash/&lt;model_key&gt;/</code></td><td>回收站</td></tr><tr><td>POST</td><td><code>/api/trash/&lt;model_key&gt;/restore/</code></td><td>恢复</td></tr><tr><td>POST</td><td><code>/api/trash/&lt;model_key&gt;/purge/</code></td><td>永久删除</td></tr><tr><td>POST</td><td><code>/api/upload/</code></td><td>Multipart 文件上传</td></tr><tr><td>GET</td><td><code>/api/inline/&lt;model_key&gt;/&lt;inline_key&gt;/</code></td><td>明细读取</td></tr><tr><td>POST</td><td><code>/api/inline/&lt;model_key&gt;/&lt;inline_key&gt;/save/</code></td><td>单组明细保存</td></tr><tr><td>POST</td><td><code>/api/action/&lt;model_key&gt;/</code></td><td>原生业务 Action</td></tr><tr><td>GET / PUT</td><td><code>/api/dashboard/</code></td><td>个人布局</td></tr><tr><td>GET</td><td><code>/api/dashboard-data/</code></td><td>工作台业务数据</td></tr><tr><td>GET</td><td><code>/api/log/</code></td><td>操作记录</td></tr><tr><td>GET</td><td><code>/api/health/</code></td><td>健康状态与版本</td></tr><tr><td>GET</td><td><code>/api/task-diagnostics/?database=default</code></td><td>默认关闭；超级管理员只读任务历史与队列汇总</td></tr></tbody></table><p>任务诊断不提供执行、重试或删除 API。公开页面/轮播、公开数据与表单的密码限速共用预算；超限为 429 与 <code>Retry-After</code>，缓存故障为通用 503，详见 <a href="./../guides/sharing-and-task-diagnostics.html">指南</a>。</p><p>系统设置保存使用 <code>PUT</code> 或 <code>POST /api/config/save/</code>，需要站点配置修改权限。</p><h2 id="页面与数据入口" tabindex="-1">页面与数据入口 <a class="header-anchor" href="#页面与数据入口" aria-label="Permalink to &quot;页面与数据入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>相对地址</th><th>内容</th></tr></thead><tbody><tr><td>GET / POST</td><td><code>/api/pages/</code></td><td>按当前资源范围读取或创建页面</td></tr><tr><td>GET</td><td><code>/api/share/&lt;uuid&gt;/</code></td><td>公开入口，继续核对状态、令牌和密码</td></tr><tr><td>POST</td><td><code>/api/share/&lt;uuid&gt;/submit/</code></td><td>公开页面表单提交与去重</td></tr><tr><td>GET</td><td><code>/api/pages/&lt;id&gt;/submissions/</code></td><td>当前资源管理范围内的答卷</td></tr><tr><td>GET / POST</td><td><code>/api/screen-playlists/</code></td><td>大屏轮播管理</td></tr><tr><td>POST</td><td><code>/api/graphql/</code></td><td>Session/CSRF 下的受限只读 GraphQL</td></tr><tr><td>GET</td><td><code>/api/datasets/catalog/</code></td><td>模型、字段与运算能力目录</td></tr><tr><td>GET / POST</td><td><code>/api/datasets/</code></td><td>数据集管理</td></tr><tr><td>POST</td><td><code>/api/datasets/&lt;id&gt;/publish/</code></td><td>发布不可变查询版本</td></tr><tr><td>POST</td><td><code>/api/datasets/&lt;id&gt;/execute/</code></td><td>显式版本、参数及当前权限执行</td></tr><tr><td>GET / POST</td><td><code>/api/reports/</code></td><td>自助报表管理</td></tr><tr><td>POST</td><td><code>/api/reports/&lt;id&gt;/execute/</code></td><td>报表执行</td></tr><tr><td>GET / POST</td><td><code>/api/report-boards/</code></td><td>跨报表看板管理</td></tr><tr><td>POST</td><td><code>/api/data/graphql/</code></td><td>独立只读服务凭据的受限 GraphQL</td></tr><tr><td>POST</td><td><code>/api/data/datasets/&lt;id&gt;/versions/&lt;number&gt;/</code></td><td>独立只读服务执行固定版本</td></tr></tbody></table><p>所有路径相对于实际挂载点。详细定义、实参与预算见 <a href="./../data/graphql.html">GraphQL</a>、<a href="./../data/datasets.html">数据集</a>、<a href="./../data/reports.html">报表</a> 和 <a href="./../data/events-and-services.html">只读服务</a>。 资源管理权不会自动授予源模型的业务数据权限；外部服务的 Bearer 不能访问管理写入接口，公开分享也不能执行私有报表。</p><p>源码新增的答卷后台导出入口为 <code>GET/POST /api/pages/&lt;id&gt;/submission-exports/</code>、<code>GET/DELETE /api/pages/&lt;id&gt;/submission-exports/&lt;run_id&gt;/</code> 与 <code>GET /api/pages/&lt;id&gt;/submission-exports/&lt;run_id&gt;/download/</code>。这些接口尚未包含在 1.0.0 中，权限、创建请求和预算见 <a href="./../guides/operations-and-submission-exports.html">后台导出指南</a>。任务告警通过宿主命令发送，不新增网页执行 API。</p><h2 id="json-响应" tabindex="-1">JSON 响应 <a class="header-anchor" href="#json-响应" aria-label="Permalink to &quot;JSON 响应&quot;">​</a></h2><p>成功：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span></code></pre></div><p>失败：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;error&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;校验失败&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;errors&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;该名称已存在&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]}}</span></span></code></pre></div><p>部分错误还包含 <code>context</code>，例如验证码是否已经启用。除了检查 HTTP 状态，也应检查 <code>ok</code>。</p><h2 id="登录与-csrf" tabindex="-1">登录与 CSRF <a class="header-anchor" href="#登录与-csrf" aria-label="Permalink to &quot;登录与 CSRF&quot;">​</a></h2><p>登录前读取配置，登录后读取账号信息，并按返回的 <code>csrf_token</code>、<code>csrf_cookie_name</code> 管理后续请求。登录会轮换 CSRF；不要把旧令牌永久缓存。</p><p>写入请求携带会话与 <code>X-CSRFToken</code>。已有前端客户端处理了 HttpOnly、会话 CSRF、自定义名称和会话切换取消，扩展组件优先复用该客户端。</p><h2 id="主表保存" tabindex="-1">主表保存 <a class="header-anchor" href="#主表保存" aria-label="Permalink to &quot;主表保存&quot;">​</a></h2><p>以下结构对应<a href="./../getting-started/quickstart.html">第一个业务模块</a>中的模型：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;客户门户升级&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;draft&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;budget&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;12000.50&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;模型目录与明细需求整理&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>新增不传 <code>id</code>；编辑时在外层提供原始 <code>id</code>。<code>data</code> 必须是对象，合法空表单使用 <code>{&quot;data&quot;: {}}</code>。JSON 请求使用 <code>application/json</code> 或 <code>+json</code>；上传和原生 Action 表单继续使用相应表单格式。</p><p>金额、大整数主键和字符主键按原值传递，不转换为浮点数。字段内部的 JSON、布尔和空值由实际表单解析。</p><h2 id="分页、筛选与标识" tabindex="-1">分页、筛选与标识 <a class="header-anchor" href="#分页、筛选与标识" aria-label="Permalink to &quot;分页、筛选与标识&quot;">​</a></h2><p>列表常用参数为 <code>q</code>、<code>page</code>、<code>page_size</code>、<code>order_by</code>，单页上限 100。筛选通过 <code>f_&lt;key&gt;</code> 传递，但值必须来自接口元数据中的实际选项，不能直接假设 <code>f_status=draft</code> 就是该项目的筛选编码。</p><p>特殊主键优先使用详情查询形式：<code>/api/detail/projects.project/?object_id=...</code>。对查询值正确 URL 编码；旧的主键路径形式也继续兼容。</p><p>关联解析与导出可使用 <code>ids_json</code>，其内容是 JSON 数组，例如 <code>[&quot;crm/2026,a&quot;, &quot;partner#1&quot;]</code>。空数组表示明确的空选择；损坏的 JSON 不会退回到导出全部记录。</p><p>JSON 精确文本来源、凭据意图、明细上下文请使用各组件章节的契约。自定义客户端不能只复制视觉控件而省略服务端权限检查。</p>`,30)])])}const E=d(i,[["render",o]]);export{k as __pageData,E as default};
